import base64,zlib,json,hashlib,subprocess,sys,copy,importlib.util
from pathlib import Path
reporter=Path('/kaggle/working/build_reliability_report.py');reporter.write_bytes(zlib.decompress(base64.b64decode('')))
out=Path('/kaggle/working/out');out.mkdir()
root=Path('/kaggle/input');found=list(root.rglob('reliability_aggregate.json'));assert len(found)==1
aggregate=found[0];data=json.loads(aggregate.read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
protocols=[p for p in root.rglob('protocol.json') if sha(p)==data['protocol_sha256']];assert len(protocols)==1
spec=importlib.util.spec_from_file_location('reporter',reporter);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
checks=[]
module.validate(data,sha(protocols[0]),True);checks.append('complete development fixture accepted with explicit scope')
for label,example,protocol_hash,development in [
 ('single user cannot become independent report',data,sha(protocols[0]),False),
 ('missing original per-seed row rejected',dict(data,per_seed=data['per_seed'][:-1]),sha(protocols[0]),True),
 ('protocol mismatch rejected',data,'0'*64,True),
 ('duplicate method summary rejected',dict(data,population=data['population']+[data['population'][0]]),sha(protocols[0]),True)]:
 try:module.validate(example,protocol_hash,development)
 except ValueError:checks.append(label)
 else:raise AssertionError(label)
(out/'report_guard_checks.json').write_text(json.dumps(dict(git_commit='379f9d78aa52d7cb36bb33f66ff87cae78fc1ae7',checks=checks,scope='real development aggregate only; no independent outcome or efficacy evidence'),indent=2))
subprocess.run([sys.executable,str(reporter),'--aggregate',str(aggregate),'--protocol',str(protocols[0]),'--out-dir',str(out/'development_report'),'--git-commit','379f9d78aa52d7cb36bb33f66ff87cae78fc1ae7','--development-only'],check=True)
